import { type Component } from 'solid-js';
import {
  combineStyles,
  type NodeStyles,
  type ElementNode,
} from '@solidtv/solid';
import { chainFunctions } from './utils/chainFunctions.js';
import {
  handleNavigation,
  navigableForwardFocus,
  defaultTransitionBack,
  defaultTransitionForward,
} from './utils/handleNavigation.js';
import type { RowProps } from './types.js';
import { scrollRow } from './utils/withScrolling.js';

const RowStyles: NodeStyles = {
  display: 'flex',
  gap: 30,
};

function scrollToIndex(this: ElementNode, index: number, options?: { noFocus?: boolean }) {
  const lastSelected = this.selected;
  this.selected = index;
  scrollRow(index, this, undefined, lastSelected === index ? undefined : lastSelected);
  if (!options?.noFocus) {
    this.children[index]?.setFocus();
  }
}

const onLeft = handleNavigation('left');
const onRight = handleNavigation('right');

export const Row: Component<RowProps> = (props) => {
  return (
    <view
      transitionLeft={defaultTransitionBack}
      transitionRight={defaultTransitionForward}
      {...props}
      selected={props.selected || 0}
      onLeft={/* @once */ chainFunctions(props.onLeft, onLeft)}
      onRight={/* @once */ chainFunctions(props.onRight, onRight)}
      forwardFocus={navigableForwardFocus}
      scrollToIndex={scrollToIndex}
      onLayout={
        /* @once */
        props.selected
          ? chainFunctions(props.onLayout, scrollRow)
          : props.onLayout
      }
      onSelectedChanged={
        /* @once */ chainFunctions(
          props.onSelectedChanged,
          props.scroll !== 'none' ? scrollRow : undefined,
        )
      }
      style={/* @once */ combineStyles(props.style, RowStyles)}
    />
  );
};
